<?php
declare(strict_types=1);
require __DIR__.'/TestDb.php';
require dirname(__DIR__).'/app/Station.php';
use Petrol\{Station,Problem};
use function Petrol\uid;
$count=0;
function check_edit(bool $ok,string $label):void{global $count;if(!$ok)throw new RuntimeException('FAIL '.$label);echo 'PASS '.$label.PHP_EOL;$count++;}
function deny_edit(callable $fn,string $label):void{try{$fn();}catch(Problem $e){check_edit(true,$label);return;}throw new RuntimeException('FAIL accepted '.$label);}
try{
$db=test_database();$s=new Station($db);$u=$s->setup(['owner_name'=>'Owner','username'=>'owner','password'=>'Pump-edit-test-2026','station_name'=>'Isolated edit tests']);
$category=$s->saveCategory(['code'=>'FUEL','name'=>'Fuel'],$u);
$product=$s->saveProduct(['sku'=>'P92','name'=>'Petrol','quantity'=>'1000','cost'=>'250','price'=>'300','category_id'=>$category['id']],$u);
$fuel=$s->master('fuel',['code'=>'PET','name'=>'Petrol','price'=>'300'],$u);
$tank=$s->master('tank',['code'=>'T1','name'=>'Tank','fuel_type_id'=>$fuel['id'],'capacity_liters'=>'2000','opening_liters'=>'1000'],$u);
$pump=$s->savePump(['code'=>'P1','name'=>'Pump 1','product_id'=>$product['id'],'tank_id'=>$tank['id'],'start_meter'=>'100','end_meter'=>'100'],$u);
$employee=$s->saveEmployee(['code'=>'DAY','name'=>'Day operator','shift_type'=>'day'],$u);
$night=$s->saveEmployee(['code'=>'NIGHT','name'=>'Night operator','shift_type'=>'night'],$u);
$sale=function($start,$close)use($s,$u,$pump,$employee,$product,$db){$d=['request_key'=>uid(),'sale_date'=>$s->meterToday(),'pump_id'=>$pump['id'],'employee_id'=>$employee['id'],'shift_type'=>'day','starting_meter'=>$start,'closing_meter'=>$close,'product_id'=>$product['id'],'price_cents'=>$s->find('products',$product['id'])['price_cents']];return $s->workOnce('pump_meter_sale',$d,$u,fn()=>$s->saveMeterSale($d,$u));};
$data=function($id,$close,array $extra=[])use($s,$u){$c=$s->meterEdit(['id'=>$id],$u);return array_merge(['request_key'=>uid(),'id'=>$id,'version'=>$c['version'],'next_id'=>$c['next']['id']??'','closing_meter'=>$close,'employee_id'=>$c['row']['employee_id'],'shift_type'=>$c['row']['shift_type']],$extra);};
$update=function($d,$user=null)use($s,$u){$user=$user??$u;return $s->workOnce('pump_meter_update',$d,$user,fn()=>$s->updateMeterSale($d,$user));};
$a=$sale('100','110');$id=$a['id'];$d=$data($id,'112');$result=$update($d);
check_edit($s->find('pump_meter_sales',$id)['liters_ml']===12000,'Latest sale quantity updates');
check_edit($s->find('products',$product['id'])['stock_milli']===988000&&$s->balance($tank['id'])===988000,'Increasing a reading deducts only the extra product and tank volume');
check_edit($s->find('pumps',$pump['id'])['start_meter_ml']===112000&&(int)$db->value('SELECT last_meter_ml FROM nozzles WHERE pump_id=?',[$pump['id']])===112000,'Live pump and nozzle readings follow the corrected latest sale');
check_edit($s->find('sales',$id)['total_cents']===360000&&(int)$db->value('SELECT line_cents FROM sale_items WHERE sale_id=?',[$id])===360000,'Receipt and item totals match the corrected sale');
check_edit($s->find('sales',$id)['cost_cents']===300000&&$s->find('pump_meter_sales',$id)['profit_cents']===60000,'Cost and profit are recomputed with exact original rates');
check_edit($update($d)===$result&&$s->balance($tank['id'])===988000,'Retry of committed edit neither repeats stock deduction nor fails stale revision');
$d['closing_meter']='113';deny_edit(fn()=>$update($d),'Successful request key cannot be reused for a changed edit');
$update($data($id,'108'));check_edit($s->find('products',$product['id'])['stock_milli']===992000&&$s->balance($tank['id'])===992000,'Reducing a reading restores only its difference');
check_edit((int)$db->value("SELECT COUNT(*) FROM stock_movements WHERE kind='sale' AND reference_id=?",[$id])===1&&(int)$db->value("SELECT COUNT(*) FROM stock_movements WHERE kind='adjustment' AND reference_id=?",[$id])===2,'Corrections append stock adjustments and retain the original movement');
$stale=$data($id,'109');$update($data($id,'108',['employee_id'=>$night['id'],'shift_type'=>'night']));
deny_edit(fn()=>$update($stale),'Concurrent edit cannot overwrite a newer employee assignment');
check_edit($s->find('pump_meter_sales',$id)['employee_name']==='Night operator'&&$s->balance($tank['id'])===992000,'Employee and shift edit does not move stock');
$db->run('UPDATE products SET price_cents=40000,cost_cents=26000 WHERE id=?',[$product['id']]);
$b=$sale('108','118');$next=$b['id'];
deny_edit(fn()=>$update($data($id,'109',['next_id'=>''])),'An earlier reading edit must acknowledge the following sale');
$update($data($id,'109'));
check_edit($s->find('pump_meter_sales',$id)['liters_ml']===9000&&$s->find('pump_meter_sales',$next)['liters_ml']===9000,'Earlier closing and following opening change together without a gap');
check_edit($s->find('pump_meter_sales',$next)['starting_ml']===109000,'Following sale starts at the corrected boundary');
check_edit($s->find('pump_meter_sales',$id)['amount_cents']===270000&&$s->find('pump_meter_sales',$next)['amount_cents']===360000,'Both entries retain their own historical selling prices');
check_edit($s->find('pump_meter_sales',$id)['cost_cents']===225000&&$s->find('pump_meter_sales',$next)['cost_cents']===234000,'Both entries retain their own historical cost rates');
check_edit($s->find('products',$product['id'])['stock_milli']===982000&&$s->balance($tank['id'])===982000,'Boundary correction keeps combined stock consumption unchanged');
check_edit($s->find('pumps',$pump['id'])['start_meter_ml']===118000,'Earlier correction preserves latest live meter');
$snap=$s->find('pump_meter_sales',$id);
deny_edit(fn()=>$update($data($id,'118')),'Boundary cannot reach the following closing meter');
check_edit($s->find('pump_meter_sales',$id)===$snap,'Invalid boundary leaves original row unchanged');
deny_edit(fn()=>$update($data($id,'100')),'Closing at original opening is rejected');
deny_edit(fn()=>$update($data($id,'109.0001')),'Four-decimal correction is rejected');
deny_edit(fn()=>$update($data($id,'109',['starting_meter'=>'99'])),'Client cannot rewrite opening meter');
deny_edit(fn()=>$update($data($id,'109',['price_cents'=>1])),'Client cannot rewrite historical selling price');
deny_edit(fn()=>$update($data($id,'109',['pump_id'=>'other'])),'Client cannot move a sale to another pump');
deny_edit(fn()=>$update($data($id,'109',['employee_id'=>$employee['id'],'shift_type'=>'night'])),'Employee must belong to selected shift');
$stale=$data($id,'108');$s->collectMeterCash(['id'=>$id,'amount'=>'1000','reference'=>'PARTIAL'],$u);
deny_edit(fn()=>$update($stale),'New cash collection invalidates an already-open edit');
deny_edit(fn()=>$update($data($id,'101')),'Correction cannot reduce sale below collected cash');
deny_edit(fn()=>$update($data($id,'109',['employee_id'=>$employee['id'],'shift_type'=>'day'])),'Collected cash cannot be reassigned to a different employee');
$s->collectMeterCash(['id'=>$next,'amount'=>'3600','reference'=>'FULL'],$u);
deny_edit(fn()=>$update($data($id,'110')),'Correction protects collected cash on the following sale too');
check_edit($s->find('pump_meter_sales',$id)['closing_ml']===109000&&$s->find('pump_meter_sales',$next)['starting_ml']===109000,'Rejected neighbour correction is atomic');
$update($data($id,'108'));
check_edit((int)$db->value('SELECT SUM(amount_cents) FROM sale_payments')===460000,'Corrections never rewrite actual cash receipts');
$due=$s->meterReport(['scope'=>'due'],$u);check_edit($due['totals']['due_cents']===180000,'Outstanding collection balances reflect corrected amounts');
$viewer=array_merge($u,['role'=>'viewer']);$other=array_merge($u,['id'=>'other-cashier','role'=>'cashier']);$cashier=array_merge($u,['role'=>'cashier']);
deny_edit(fn()=>$s->meterEdit(['id'=>$id],$viewer),'Viewer cannot open editor');
deny_edit(fn()=>$update($data($id,'108'),$viewer),'Viewer cannot update sales');
deny_edit(fn()=>$s->meterEdit(['id'=>$id],$other),'Cashier cannot edit another operator’s sale');
$safe=$s->meterEdit(['id'=>$id],$cashier);check_edit(!isset($safe['row']['cost_cents'])&&!isset($safe['next']['cost_cents']),'Cashier edit preview does not expose costs');
$update($data($id,'108'),$cashier);check_edit(true,'Cashier can update their own sale');
$db->run('UPDATE pump_meter_sales SET sale_date=? WHERE id=?',['2000-01-01',$id]);check_edit($s->meterEdit(['id'=>$id],$u)['row']['id']===$id,'Manager can open previous-day sale from Overview');deny_edit(fn()=>$s->meterEdit(['id'=>$id],$cashier),'Cashier cannot edit previous-day sales');$db->run('UPDATE pump_meter_sales SET sale_date=? WHERE id=?',[$s->meterToday(),$id]);
$db->run('UPDATE pump_meter_sales SET sale_date=? WHERE id=?',['2099-01-01',$next]);deny_edit(fn()=>$update($data($id,'109')),'Boundary correction cannot modify another day');$db->run('UPDATE pump_meter_sales SET sale_date=? WHERE id=?',[$s->meterToday(),$next]);
$stale=$data($next,'119');$c=$sale('118','120');deny_edit(fn()=>$update($stale),'New subsequent sale invalidates an already-open edit');
$last=$c['id'];$before=$s->find('products',$product['id']);deny_edit(fn()=>$update($data($last,'9999')),'Correction cannot oversell product stock');check_edit($s->find('products',$product['id'])===$before,'Failed stock correction rolls back inventory');
$tankStock=$s->balance($tank['id']);$db->run('UPDATE tanks SET capacity_ml=? WHERE id=?',[$tankStock,$tank['id']]);deny_edit(fn()=>$update($data($last,'119')),'Returning fuel cannot exceed tank capacity');check_edit($s->find('products',$product['id'])===$before&&$s->balance($tank['id'])===$tankStock,'Tank validation rolls back the product adjustment too');$db->run('UPDATE tanks SET capacity_ml=2000000 WHERE id=?',[$tank['id']]);
$nozzle=(string)$db->value('SELECT id FROM nozzles WHERE pump_id=?',[$pump['id']]);
$tank2=$s->master('tank',['code'=>'T2','name'=>'Other tank','fuel_type_id'=>$fuel['id'],'capacity_liters'=>'2000','opening_liters'=>'1000'],$u);
$db->run('UPDATE nozzles SET tank_id=? WHERE id=?',[$tank2['id'],$nozzle]);deny_edit(fn()=>$update($data($last,'121')),'Changed tank connection cannot redirect a historical correction');$db->run('UPDATE nozzles SET tank_id=? WHERE id=?',[$tank['id'],$nozzle]);
$s->openShift(['label'=>'Legacy','opening_cash'=>'0','nozzle_ids'=>[$nozzle]],$u);
deny_edit(fn()=>$update($data($last,'121')),'Open billing shift prevents a meter boundary correction');
$update($data($last,'120',['employee_id'=>$night['id'],'shift_type'=>'night']));check_edit(true,'Employee correction remains available when a billing shift owns the meter');
check_edit((int)$db->value("SELECT COUNT(*) FROM audit_logs WHERE action='edit_meter_sale'")>=8,'Corrections retain before/after audit records');
check_edit((int)$db->value('SELECT COUNT(*) FROM sales')===3,'All edits update existing rows without adding duplicate sales');
$standalone=$s->savePump(['code'=>'P2','name'=>'Standalone','product_id'=>$product['id'],'start_meter'=>'0','end_meter'=>'0'],$u);
$r=$s->saveMeterSale(['request_key'=>uid(),'sale_date'=>$s->meterToday(),'pump_id'=>$standalone['id'],'employee_id'=>$employee['id'],'shift_type'=>'day','starting_meter'=>'0','closing_meter'=>'1','product_id'=>$product['id'],'price_cents'=>40000],$u);$productBefore=$s->find('products',$product['id']);$tankBefore=$s->balance($tank['id']);
$update($data($r['id'],'2'));
check_edit($s->find('products',$product['id'])['stock_milli']===$productBefore['stock_milli']-1000,'Standalone pump edit adjusts product stock without requiring a nozzle');
check_edit($s->balance($tank['id'])===$tankBefore&&$s->find('pumps',$standalone['id'])['start_meter_ml']===2000,'Standalone edit advances its meter without touching a tank');
echo "\n$count pump edit checks passed.\n";
}catch(Throwable $e){fwrite(STDERR,(string)$e.PHP_EOL);exit(1);}
